contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single test function: takes depositor address (must be this contract), deposit amount, and withdraw amount
    // We use this contract as caller to deposit and later withdraw, observing behavior via require on success
    function runTest(uint256 depositAmount, uint256 withdrawAmount) public {
        // ensure this contract has enough balance to perform deposit
        require(address(this).balance >= depositAmount);

        // record contract balance of c before deposit
        uint256 before = address(c).balance;

        // perform deposit (may overflow in mutant)
        c.deposit{value: depositAmount}();

        // record contract balance of c after deposit
        uint256 after = address(c).balance;

        // The general rule: after >= before (contract's balance must not decrease due to deposit)
        // This will hold in original (assert prevents overflow in balances mapping leading to unintended effects)
        // and be violated in mutant where overflow removal can cause wrap and inconsistent state visible via balance
        assert(after >= before);
    }

    // Allow contract to receive ether so tests can fund it
    receive() external payable {}
}

