        // require that the test can send `amount` wei to C
        require(amount > 0, "amount must be > 0");
        require(address(this).balance >= amount, "insufficient balance to send");

        bool reverted;
        try c.deposit{value: amount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: for any positive amount we attempt to deposit, deposit should not revert.
        assert(reverted == false);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // depositAmount is the Ether sent to c.deposit
    function run(uint256 depositAmount) public payable {
        require(address(this).balance >= depositAmount, "insufficient balance to send");
        // We want a prior nonzero balance for this contract's address in c. Achieve this by calling deposit once with a small amount.
        bool firstReverted; try c.deposit{value: 1}() { firstReverted = false; } catch { firstReverted = true; }
        // Now attempt a second deposit that could overflow if balances[msg.sender] + depositAmount <= balances[msg.sender]
        bool secondReverted; try c.deposit{value: depositAmount}() { secondReverted = false; } catch { secondReverted = true; }
