pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: depositor address and amount to deposit
    function testFuzz_property(address depositor, uint256 amount) public {
        // keep depositor as a nonzero address
        vm.assume(depositor != address(0));
        // bound amount to a wide domain including large values (0 allowed)
        uint256 amt = bound(amount, 0, type(uint256).max);

        // arrange: fund the depositor so they can send amt
        vm.deal(depositor, amt);

        // act: perform deposit from depositor
        vm.prank(depositor);
        bool ok;
        try c.deposit{value: amt}() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: if the call succeeded, the depositor's recorded balance equals the sent amount
        // (We observe c via its public balances getter). This holds for the reference because it asserts against overflow;
        // the mutant that removed the assert can overflow and wrap, causing balances(depositor) != amt for some inputs.
        if (ok) {
            assertTrue(c.balances(depositor) == amt);
        } else {
            // if deposit reverted, then balances must be zero (no state change visible) -- reference never reverts for valid sends
            assertTrue(c.balances(depositor) == 0);
        }
    }
}

