pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzz depositor and amount; the general rule: deposit never decreases caller's balance
    function testFuzz_property(address depositor, uint256 amount) public {
        // avoid the zero-address edge-case for sending funds
        vm.assume(depositor != address(0));

        // ensure depositor has ETH to send
        vm.deal(depositor, amount);

        // read balance before
        uint256 before = address(c).balance;
        // read depositor-specific stored balance via auto getter is not available (mapping not public),
        // but we can observe invariant via net non-decrease of address(c).balance when caller deposits
        // (deposit forwards value into contract storage/ether). The correct contract will always increase
        // the contract's balance by exactly amount when deposit succeeds; the mutant can wrap internal
        // accounting causing later inconsistencies but the simplest universal observable that fails
        // under overflow in internal balances is that a successful deposit call should not reduce
        // the contract's ether balance. So we assert the contract's balance does not decrease.

        // perform the deposit as the depositor
        vm.prank(depositor);
        // call deposit with value; catch any revert and treat as failure (ok=false)
        bool ok;
        try c.deposit{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }

        // after the call, the contract's ETH balance must be >= before if the deposit call succeeded,
        // and if the call reverted, nothing changed (balance unchanged). Thus contract balance never < before.
        uint256 after = address(c).balance;

        // Single assertion: contract balance never decreases as a result of the deposit invocation
        assertTrue(after >= before);
    }
}

