pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address depositor, uint256 amount) public {
        // keep depositor as any address; amount can be any uint256
        vm.deal(depositor, amount);

        // record pre-state via public getter: balances is a private mapping in original C,
        // but Foundry test must read only public surface. The original C declares
        // "mapping(address => uint256) balances;" (no public) so there is no getter.
        // However the required test must observe c only via public surface. We can
        // observe address(c).balance which reflects contract's ETH balance; but the
        // intended invariant is about stored balances mapping. To create a valid
        // universal property that the reference satisfies and the mutant breaks,
        // we instead observe that the contract-level balance (address(c).balance)
        // never decreases when a depositor sends ETH via deposit(): it should
        // increase by the sent amount. The mutant can overflow an internal mapping
        // and still transfer (no balance change), but removing the assert cannot
        // cause contract ETH to decrease, so we instead assert per-depositor
        // recorded mapping behaviour via calling deposit and then performing a
        // subsequent withdraw attempt: the reference guarantees that if deposit
        // increments the depositor's recorded balance without overflow, then a
        // withdraw of that new amount succeeds; the mutant's overflow can make
        // recorded balance smaller, causing withdraw(amount) to revert when
        // amount > recorded balance. Thus we observe withdraw's success via try/catch.

        // To make this work while satisfying constraints: we will perform two steps
        // - First, perform a deposit of amount from depositor.
        // - Then, try to withdraw that same amount from depositor. In the correct
        //   contract, withdraw(amount) will succeed because recorded balance >= amount.
        // - In the mutant, an overflow in the mapping may reduce the recorded balance
        //   so withdraw(amount) can revert. We assert that withdraw succeeds (ok==true).

        // Ensure depositor has the ETH and act as depositor
        vm.startPrank(depositor);
        try c.deposit{value: amount}() {
            // deposit succeeded (or did revert, in which case we catch below);
        } catch {
            // if deposit reverts, then the reference also would revert; but
            // deposit in reference only uses assert on overflow which reverts in
            // the overflow case; to keep a universal property that holds for all
            // inputs on reference, we must avoid inputs where reference reverts.
            vm.stopPrank();
            return; // skip this input since reference deposit reverted (due to overflow assert)
        }
        bool ok;
        try c.withdraw(amount) {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        // The correct contract: if deposit succeeded then recorded balance >= amount,
        // so withdraw(amount) must succeed (ok == true). The mutant can overflow the
        // internal mapping and make recorded balance < amount, causing withdraw to revert (ok == false).
        assertTrue(ok);
    }
}

contract InvMutTest {
