        uint256 before = address(this).balance;

        // call deposit forwarded from this contract to c on behalf of this contract
        // note: c.deposit is external; we call it and forward amt wei
        c.deposit{value: amt}();

        // record our balance after
        uint256 after = address(this).balance;

        // General rule: calling deposit never causes this test contract to gain ETH
