    function testFuzz_property(uint256 msgValue, address actor) public {
        // keep actor non-zero to be a valid address
        vm.assume(actor != address(0));
        // bound msgValue to a reasonable max so vm.deal won't overflow in test environment
        uint256 value = bound(msgValue, 0, 1 ether);

        // fund actor so they can send value (even zero is allowed)
