contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function: deposit once and check balance change equals amount
    function runTest(uint256 initialTopUp, uint256 depositAmount) public {
        // ensure this test contract has enough ETH to send
        require(address(this).balance >= initialTopUp + depositAmount);

        // If needed, top up the caller's balance in C so initial balance may be non-zero.
        // Use msg.sender (this contract) as depositor by calling c.deposit with value.
        if (initialTopUp > 0) {
            c.deposit{value: initialTopUp}();
        }

        // Read balance before the decisive deposit via public observable: address(c).balance can't tell per-user balance.
        // So we infer per-user balance by performing a refund: call refund to get entire balance, observe transfer by comparing this contract's balance before/after,
        // then re-deposit the refunded amount to restore state. This sequence is allowed through c's public surface.

        // Record our external balance before refund
        uint256 before = address(this).balance;
        // Trigger refund: this will transfer our entire stored balance from c to this contract and set c's stored balance for us to 0
        c.refund();
        uint256 after = address(this).balance;

        // The refunded amount equals our prior per-user balance in c
        uint256 priorUserBalance = after - before;

        // Restore that prior balance into c so final check compares from same starting point
        if (priorUserBalance > 0) {
            c.deposit{value: priorUserBalance}();
        }

        // Now perform the decisive deposit of depositAmount
        c.deposit{value: depositAmount}();

        // To observe the per-user balance after deposit, perform refund again and measure received amount
        uint256 before2 = address(this).balance;
        c.refund();
        uint256 after2 = address(this).balance;

        uint256 finalUserBalance = after2 - before2;

        // The property: final balance equals prior balance + depositAmount
