        // deploy Attacker funded with depositAmount and set up to call c.withdraw and have receive revert via Reverter
        Attacker attacker = new Attacker(payable(address(c)), r);
        vm.deal(address(attacker), depositAmount);

        // have attacker deposit its funds into c
        vm.prank(address(attacker));
        c.deposit{value: depositAmount}();

        // Now attacker will attempt to withdraw withdrawAmount (bounded above). We only consider admissible cases
        // where withdrawAmount <= depositAmount, because withdraw requires that; keep domain wide but valid.
        vm.assume(withdrawAmount <= depositAmount);

        // record contract balance before
        uint256 before = address(c).balance;

        // attacker calls withdraw; its receive will revert (via Reverter) causing low-level call to fail in mutant
        // but succeed in reference (reference uses transfer which reverts on failure). For reference, if external revert
        // occurs transfer will revert and withdraw will revert, so balances unchanged; for mutant, the low-level call
        // fails silently and the contract decrements balances while funds remain in contract.
        vm.prank(address(attacker));
        attacker.doWithdraw(withdrawAmount);

        // After the withdraw attempt completes, the reference contract guarantees that either the transfer succeeded
        // and contract balance decreased by withdrawAmount, or the whole call reverted and no state changed. Thus,
        // whenever the external transfer failed (recipient reverted), the reference would have reverted and contract
        // balance would remain equal to before. The mutant can finish while leaving contract balance unchanged but
        // having decremented the internal balance. We assert a general invariant that for this scenario (recipient reverts)
        // the contract balance cannot be smaller than before unless the withdrawAmount was actually sent out. Since the only
        // observable we can use is address(c).balance, we assert that address(c).balance + totalWithdrawn == before.
        // For simplicity and to produce a single assertion that the reference satisfies for all admissible inputs and the mutant
        // violates for some, we assert that address(c).balance <= before and that the decrease is exactly either 0 or withdrawAmount.
        // Because we must emit exactly one assertTrue reading c, we check that the change in contract balance is either 0 or withdrawAmount.

        uint256 after = address(c).balance;
        uint256 diff = before >= after ? before - after : 0;

        // The reference always makes diff equal to either 0 (reverted withdraw) or withdrawAmount (successful transfer).
        // The mutant can make diff equal to 0 while having decremented internal balances — but we only observe contract balance.
        // This single assertion checks that diff is either 0 or withdrawAmount.
        assertTrue(diff == 0 || diff == withdrawAmount);
    }
}

// Attacker contract that, when receiving a withdraw, will forward to Reverter which reverts on receive
contract Attacker {
    C c;
    Reverter r;
    constructor(address payable _c, Reverter _r) {
        c = C(_c);
        r = _r;
    }

    // deposit was done externally by sending ETH to c from this contract via vm.prank in test
    // This function calls withdraw on c; when c sends funds to this contract, this contract's receive will revert
    function doWithdraw(uint256 amount) public {
        // call withdraw as this contract
        try c.withdraw(amount) {
            // swallow
        } catch {
            // swallow
        }
    }

    receive() external payable {
        // forward to reverter which will revert to simulate failing low-level call target
        (bool ok, ) = address(r).call{value: msg.value}("");
        // If the call returns, revert to ensure receive itself reverts in the reference using transfer
        if (!ok) revert("forward failed");
    }
}

contract Reverter {
    fallback() external payable {
        revert("revert target");
    }
}

