        amt = bound(amt, 1, 1 ether);

        // deploy victim address which may revert on receive
        ReceiverHelper r = new ReceiverHelper(willRevert);

        // fund the recipient so it can be a msg.sender for deposits (not required) and fund the test
        vm.deal(address(this), 2 ether);

        // deposit into contract from this test address
        c.deposit{value: amt}();

        // ensure contract recorded the deposit
        // now simulate withdraw by having the caller be the ReceiverHelper
        // give ReceiverHelper some balance to allow it to call withdraw if needed
        vm.deal(address(r), 1 ether);

        // prank as the receiver (acts as msg.sender for withdraw)
        vm.startPrank(address(r));
        // first, credit balances mapping: we need balances[msg.sender] >= amt
        // Since only deposit modifies balances for msg.sender, have the helper deposit
        // As EOA can't initiate from helper, we let helper call deposit by calling through vm.prank
        // but deposit uses msg.sender; we want balances[address(r)] == amt
        // So have helper deposit its own funds
