        // record contract balance before withdraw
        uint256 before = address(c).balance;

        // attempt withdraw; for the reference contract this should revert when willRevert==true,
        // but the mutant may swallow the low-level call failure and succeed, decrementing balances without sending Ether
        bool ok;
        try c.withdraw(amt) {
            ok = true;
        } catch {
            ok = false;
        }

        // stop prank
        vm.stopPrank();

