        // but the mutant can return ok==true for some inputs. We assert the reference's universal property here by
        // checking that when willRevert == true the call did not succeed (ok == false). This will hold for the
        // reference implementation for all inputs but fail on the mutant for some input.
        assertTrue(!willRevert || !ok);
    }
}

// Helper that can optionally revert when receiving Ether and can call deposit on C
contract ReceiverHelper {
    bool public shouldRevert;
    constructor(bool _shouldRevert) payable {
        shouldRevert = _shouldRevert;
    }
    receive() external payable {
        if (shouldRevert) revert("revert on receive");
    }
    function callDeposit(address cAddr) external payable {
        // forward deposit to target contract so balances[msg.sender] is set
        (bool s, ) = cAddr.call{value: msg.value}(abi.encodeWithSignature("deposit()"));
        require(s, "deposit failed");
    }
