contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: depositor (actor) and amount to deposit/withdraw
    function testFuzz_property(address depositor, uint128 amt) public {
        // keep depositor non-zero and distinct from contract and test runner
        vm.assume(depositor != address(0));
        vm.assume(depositor != address(this));
        // bound amount to a reasonable non-zero value to exercise paths
        uint256 amount = bound(uint256(amt), 1, 1 ether);

        // deploy a reentrant attacker that will call back into c.withdraw during its receive()
        Attacker attacker = new Attacker(address(c));

        // fund depositor and attacker
        vm.deal(depositor, amount);
        vm.deal(address(attacker), amount);

        // depositor deposits into c
        vm.prank(depositor);
        c.deposit{value: amount}();

        // attacker deposits into c so it has a balance and will be able to withdraw
        vm.prank(address(attacker));
        // attacker deposits amount so it has balance to withdraw
        c.deposit{value: amount}();

        // Now perform withdraw from attacker which will reenter during transfer if contract is vulnerable
        // We call as the attacker so msg.sender is the attacker contract
        vm.prank(address(attacker));
        // attacker attempts to withdraw exactly 'amount'
        // use try/catch to ensure call completion doesn't revert the test
        bool ok;
        try c.withdraw(amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: after withdraw completes, the stored balance for attacker equals
        // initial balance (amount) minus the requested withdraw amount. The correct contract
        // (reference) always enforces this; a reentrant-vulnerable mutant (transfer before
        // decrement) can reenter and cause the final stored balance to be < (amount - withdrawn)
        // or otherwise inconsistent. We read the public mapping via the auto getter balances(address).
        // Note: c.balances is a private variable in many patterns; here we assume the given contract
        // declared it as 'mapping(address => uint256) balances;' which makes an auto getter.
        assertTrue(c.balances(address(attacker)) == amount - amount);
    }
}

